import React, { useState, useEffect } from 'react';
import api from './api';
import AuthModal from './components/AuthModal';
import InteractiveSeating from './components/InteractiveSeating';
import GateSimulator from './components/GateSimulator';
import OrganizerStudio from './components/OrganizerStudio';
import AdminFleetMonitor from './components/AdminFleetMonitor';

function App() {
    const [user, setUser] = useState(() => {
        const saved = localStorage.getItem('tf_user');
        return saved ? JSON.parse(saved) : null;
    });
    const [activeTab, setActiveTab] = useState('catalog');
    const [events, setEvents] = useState([]);
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [tickets, setTickets] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [toasts, setToasts] = useState([]);

    const showToast = (message, type = 'info') => {
        const id = Date.now();
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3600);
    };

    const fetchEvents = async () => {
        try {
            const res = await api.get('/events');
            setEvents(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    const fetchTickets = async () => {
        if (!user) return;
        try {
            const res = await api.get('/tickets/my');
            setTickets(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (user) {
            fetchEvents();
            fetchTickets();
        }
    }, [user]);

    const handleLogout = () => {
        localStorage.removeItem('tf_token');
        localStorage.removeItem('tf_user');
        setUser(null);
        setSelectedEvent(null);
        setActiveTab('catalog');
    };

    if (!user) {
        return (
            <>
                <AuthModal onAuthSuccess={(u) => setUser(u)} showToast={showToast} />
                <ToastContainer toasts={toasts} />
            </>
        );
    }

    const filteredEvents = events.filter(ev => {
        const matchesCat = selectedCategory === 'All' || ev.category === selectedCategory;
        const matchesQuery = ev.title.toLowerCase().includes(searchQuery.toLowerCase()) || ev.venue.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCat && matchesQuery;
    });

    return (
        <div className="min-h-screen flex flex-col relative">
            {/* Spatial Ambient Background */}
            <div className="spatial-canvas">
                <div className="spatial-orb-1"></div>
                <div className="spatial-orb-2"></div>
                <div className="spatial-orb-3"></div>
            </div>

            {/* Floating visionOS Glass Dock Header */}
            <header className="sticky top-4 z-40 px-4 sm:px-6 lg:px-8">
                <div className="max-w-7xl mx-auto liquid-glass rounded-full px-4 sm:px-6 py-2.5 flex flex-wrap items-center justify-between gap-3">
                    {/* Brand */}
                    <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}>
                        <div className="w-9 h-9 rounded-full bg-white/15 border border-white/30 flex items-center justify-center text-base shadow-inner">
                            🎟️
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="font-bold text-base tracking-tight text-white">TicketFlow</span>
                            <span className="hidden sm:inline text-[10px] font-mono px-2 py-0.5 rounded-full bg-white/10 text-white/75 border border-white/15">OS 2.4</span>
                        </div>
                    </div>

                    {/* Apple Segmented Pill Navigation */}
                    <nav className="flex flex-wrap items-center gap-1 liquid-well p-1 rounded-full">
                        <button onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }} className={`px-4 py-1.5 rounded-full text-xs font-semibold transition-all ${activeTab === 'catalog' ? 'bg-white text-slate-950 shadow-md' : 'text-white/70 hover:text-white'}`}>
                            Explore
                        </button>
                        <button onClick={() => setActiveTab('tickets')} className={`flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-semibold transition-all ${activeTab === 'tickets' ? 'bg-white text-slate-950 shadow-md' : 'text-white/70 hover:text-white'}`}>
                            <span>Wallet &amp; Gate</span>
                            <span className={`text-[10px] font-mono px-1.5 py-0.2 rounded-full ${activeTab === 'tickets' ? 'bg-slate-950/15 text-slate-950' : 'bg-white/15 text-white'}`}>{tickets.length}</span>
                        </button>
                        {(user.role === 'ORGANIZER' || user.role === 'ADMIN') && (
                            <button onClick={() => setActiveTab('organizer')} className={`px-4 py-1.5 rounded-full text-xs font-semibold transition-all ${activeTab === 'organizer' ? 'bg-white text-slate-950 shadow-md' : 'text-white/70 hover:text-white'}`}>
                                Studio
                            </button>
                        )}
                        {user.role === 'ADMIN' && (
                            <button onClick={() => setActiveTab('admin')} className={`px-4 py-1.5 rounded-full text-xs font-semibold transition-all ${activeTab === 'admin' ? 'bg-white text-slate-950 shadow-md' : 'text-white/70 hover:text-white'}`}>
                                IoT Fleet
                            </button>
                        )}
                    </nav>

                    {/* Identity Capsule */}
                    <div className="flex items-center gap-3">
                        <div className="text-right hidden md:block">
                            <p className="text-xs font-semibold text-white leading-tight">{user.fullName}</p>
                            <p className="text-[10px] font-mono text-white/50">{user.role}</p>
                        </div>
                        <button onClick={handleLogout} className="px-3.5 py-1.5 rounded-full bg-white/10 hover:bg-white/20 border border-white/15 text-xs font-medium text-white/85 transition">
                            Sign Out
                        </button>
                    </div>
                </div>
            </header>

            <ToastContainer toasts={toasts} />

            <main className="relative z-10 flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {activeTab === 'catalog' && !selectedEvent && (
                    <div className="space-y-7">
                        {/* Spatial Hero Banner */}
                        <div className="liquid-glass rounded-[32px] p-7 sm:p-9 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                            <div className="max-w-2xl space-y-2.5">
                                <div className="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-white/10 border border-white/20 text-white/90 text-xs font-medium">
                                    <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping"></span>
                                    Autonomous Turnstile Access Enabled
                                </div>
                                <h1 className="text-3xl sm:text-4xl font-extrabold tracking-tight text-white">
                                    Live Events. <span className="text-white/65 font-semibold">Seamless Entry.</span>
                                </h1>
                                <p className="text-sm text-white/60 leading-relaxed">
                                    Reserve exact seats with atomic row locking, store cryptographic passes in your Wallet, and walk straight through our edge readers.
                                </p>
                            </div>

                            <div className="w-full lg:w-96 space-y-3">
                                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search artist, venue, or city..." className="w-full px-4 py-3 rounded-full liquid-well text-sm text-white placeholder-white/40 focus:outline-none focus:border-white/40 transition" />
                                <div className="flex flex-wrap gap-1.5">
                                    {['All', 'Concerts', 'Festivals', 'Theater', 'Comedy'].map(cat => (
                                        <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-3.5 py-1.5 rounded-full text-xs font-semibold transition ${selectedCategory === cat ? 'bg-white text-slate-950 shadow-sm' : 'bg-white/10 text-white/75 hover:bg-white/20'}`}>
                                            {cat}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* Frosted Event Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {filteredEvents.map(ev => (
                                <div key={ev.id} className="liquid-glass-card rounded-[30px] overflow-hidden flex flex-col justify-between">
                                    <div className="p-7 border-b border-white/10 relative">
                                        <div className="flex items-center justify-between gap-2 mb-4">
                                            <span className="px-3 py-1 rounded-full text-xs font-semibold bg-white/15 text-white border border-white/20">{ev.category}</span>
                                            <span className="px-3 py-1 rounded-full text-xs font-mono font-medium bg-emerald-400/15 text-emerald-200 border border-emerald-300/25">{ev.totalCapacity - ev.soldCount} available</span>
                                        </div>
                                        <h3 className="text-2xl font-bold tracking-tight text-white">{ev.title}</h3>
                                        <p className="text-sm text-white/70 mt-1.5">{ev.venue}</p>
                                        <p className="text-xs font-mono text-white/45 mt-1">{ev.date}</p>
                                    </div>

                                    <div className="px-7 py-5 flex items-center justify-between gap-4 bg-white/[0.02]">
                                        <div>
                                            <p className="text-[11px] uppercase tracking-wider text-white/45 font-semibold">Starting At</p>
                                            <p className="text-xl font-bold font-mono text-white">{ev.gaPrice} <span className="text-xs font-normal text-white/50">RON</span></p>
                                        </div>
                                        <button onClick={() => setSelectedEvent(ev)} className="px-6 py-2.5 rounded-full glass-pill-btn font-bold text-sm">
                                            Select Seats
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'catalog' && selectedEvent && (
                    <InteractiveSeating
                        event={selectedEvent}
                        user={user}
                        onBack={() => { setSelectedEvent(null); fetchEvents(); }}
                        onCheckoutSuccess={() => {
                            setSelectedEvent(null);
                            fetchEvents();
                            fetchTickets();
                            setActiveTab('tickets');
                        }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'tickets' && (
                    <GateSimulator
                        tickets={tickets}
                        onRefreshTickets={fetchTickets}
                        onBuyMore={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'organizer' && (
                    <OrganizerStudio events={events} onEventCreated={fetchEvents} showToast={showToast} />
                )}

                {activeTab === 'admin' && (
                    <AdminFleetMonitor showToast={showToast} />
                )}
            </main>
        </div>
    );
}

const ToastContainer = ({ toasts }) => (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2.5 max-w-sm w-full pointer-events-none px-4 sm:px-0">
        {toasts.map(t => {
            const icons = { success: '✓', warning: '!', error: '✕', info: 'i' };
            const dotColors = {
                success: 'bg-emerald-400 text-slate-950',
                warning: 'bg-amber-300 text-slate-950',
                error: 'bg-rose-500 text-white',
                info: 'bg-white text-slate-950'
            };
            return (
                <div key={t.id} className="pointer-events-auto liquid-glass flex items-center gap-3 px-4 py-3.5 rounded-full text-xs font-medium text-white shadow-2xl">
                    <span className={`w-5 h-5 rounded-full flex items-center justify-center font-bold text-[11px] shrink-0 ${dotColors[t.type]}`}>{icons[t.type]}</span>
                    <p className="leading-snug">{t.message}</p>
                </div>
            );
        })}
    </div>
);

export default App;
